import { Move } from "./dex-moves";
import { Species } from "./dex-species";

export const MOD_ID = 'cobblemon';

const cobbleMoves = new Map<string, Move>();
const cobblemonSpecies = new Map<ID, Species>();

export function registerMove(moveId: string, move: Move): Move {
	// TODO: validate as Move?
	cobbleMoves.set(moveId, eval(`(${move})`));
	return move;
}

export function registerSpecies(speciesData: AnyObject): Species {
	const species = new Species(speciesData);
	cobblemonSpecies.set(species.id, species);
	return species;
}

export function resetMoves() {
	cobbleMoves.clear();
}

export function resetSpecies() {
	cobblemonSpecies.clear();
}

export function moveByID(id: string): Move | undefined {
	return cobbleMoves.get(id);
}

export function speciesByID(id: ID): Species | undefined {
	return cobblemonSpecies.get(id);
}

export function allCachedMoves(): Move[] {
	return Array.from(cobbleMoves.values());
}

export function allCachedSpecies(): Species[] {
	return Array.from(cobblemonSpecies.values());
}
